import { ChildProcessWithoutNullStreams, spawn } from 'node:child_process';
import { EventEmitter } from 'node:events';
import { accessSync, constants, statSync } from 'node:fs';
import { delimiter, join } from 'node:path';
import * as readline from 'node:readline';

export type CecHoldMode = 'longPress' | 'repeat';
export type CecKeyType = 'volumeUp' | 'volumeDown' | 'mute' | 'powerOn' | 'powerOff';
export type CecPressType = 'single' | 'long';
export type CecPowerKeyMode = 'ignore' | 'handle';
export type CecSemanticAction =
  | 'volumeUp'
  | 'volumeDown'
  | 'muteToggle'
  | 'powerOn'
  | 'powerOff'
  | 'powerToggle';

export interface CecLogger {
  info(message: string, ...parameters: unknown[]): void;
  warn(message: string, ...parameters: unknown[]): void;
  error(message: string, ...parameters: unknown[]): void;
  debug(message: string, ...parameters: unknown[]): void;
}

export interface CecDiscoveredDevice {
  logicalAddress: string;
  logicalAddressNum: number;
  deviceType: string;
  physicalAddress: string;
  activeSource: boolean;
  vendor: string;
  osdString: string;
  isAppleTv: boolean;
}

export interface CecKeyEvent {
  logicalAddress: string;
  key: CecKeyType;
  pressType: CecPressType;
  timestamp: number;
}

export interface CecVolumeCommandEvent {
  logicalAddress: string;
  key: 'volumeUp' | 'volumeDown' | 'mute';
  isRepeat: boolean;
  timestamp: number;
}

export interface CecPowerChangeEvent {
  logicalAddress: string;
  powered: boolean;
  previous: boolean | null;
  source: 'bus' | 'key';
  timestamp: number;
}

export interface CecActionEvent {
  logicalAddress: string;
  action: CecSemanticAction;
  isRepeat: boolean;
  source: 'key' | 'bus';
  timestamp: number;
}

export interface CecTrafficFrame {
  src: string;
  dst: string;
  opcode: string;
  arg?: string;
  bytes: string[];
}

export interface CecClientOptions {
  cecClientPath?: string;
  portPath?: string;
  osdName?: string;
  hdmiPort?: number;
  holdMode?: CecHoldMode;
  holdDelayMs?: number;
  holdRepeatMs?: number;
  holdSafetyMs?: number;
  powerDebounceMs?: number;
  ignoreStandbyAfterWakeMs?: number;
  powerKeyMode?: CecPowerKeyMode;
  rescanIntervalSec?: number;
  rawSender?: (cmd: string) => void;
}

export interface ResolveCecClientOptions {
  configuredPath?: string;
  envPath?: string;
  extraSearchDirs?: string[];
  isExecutable?: (candidate: string) => boolean;
}

interface HoldState {
  key: 'volumeUp' | 'volumeDown';
  longFired: boolean;
  delayTimer: NodeJS.Timeout | null;
  repeatTimer: NodeJS.Timeout | null;
  directDelayTimer: NodeJS.Timeout | null;
  directRepeatTimer: NodeJS.Timeout | null;
  safetyTimer: NodeJS.Timeout | null;
}

interface PendingPowerTransition {
  targetState: boolean;
  source: 'bus' | 'key';
  timer: NodeJS.Timeout;
}

const PLAYBACK_LOGICAL_ADDRESSES = new Set(['3', '4', '6', '8', 'b']);

export const DEFAULT_CEC_SEARCH_DIRS = [
  '/opt/homebrew/bin',
  '/opt/homebrew/sbin',
  '/usr/local/bin',
  '/usr/local/sbin',
  '/usr/bin',
  '/bin',
  '/opt/local/bin',
  '/snap/bin',
  '/home/linuxbrew/.linuxbrew/bin',
];

function defaultIsExecutable(filePath: string): boolean {
  try {
    const st = statSync(filePath);
    if (!st.isFile()) {
      return false;
    }
    accessSync(filePath, constants.X_OK);
    return true;
  } catch {
    return false;
  }
}

/**
 * Resolve the `cec-client` executable across `PATH` and common macOS/Linux installation directories.
 * Homebridge services (launchd/systemd/Docker) frequently run with a minimal PATH that omits `/opt/homebrew/bin`.
 */
export function resolveCecClientPath(options: ResolveCecClientOptions = {}): string | null {
  const requested = options.configuredPath?.trim() || 'cec-client';
  const isExecutable = options.isExecutable ?? defaultIsExecutable;

  if (requested.includes('/') || requested.includes('\\')) {
    return isExecutable(requested) ? requested : null;
  }

  const envDirs = (options.envPath ?? process.env.PATH ?? '')
    .split(delimiter)
    .map((dir) => dir.trim())
    .filter((dir) => dir.length > 0);
  const extraDirs = options.extraSearchDirs ?? DEFAULT_CEC_SEARCH_DIRS;

  const seen = new Set<string>();
  for (const dir of [...envDirs, ...extraDirs]) {
    if (seen.has(dir)) {
      continue;
    }
    seen.add(dir);
    const candidate = join(dir, requested);
    if (isExecutable(candidate)) {
      return candidate;
    }
  }

  return null;
}

function buildAugmentedEnv(): NodeJS.ProcessEnv {
  const existingDirs = (process.env.PATH ?? '')
    .split(delimiter)
    .map((dir) => dir.trim())
    .filter((dir) => dir.length > 0);

  const merged: string[] = [];
  const seen = new Set<string>();
  for (const dir of [...existingDirs, ...DEFAULT_CEC_SEARCH_DIRS]) {
    if (!seen.has(dir)) {
      seen.add(dir);
      merged.push(dir);
    }
  }

  return {
    ...process.env,
    PATH: merged.join(delimiter),
  };
}

/**
 * Parse a `cec-client` `scan` output block into structured CEC devices.
 */
export function parseScanOutput(lines: string[]): CecDiscoveredDevice[] {
  const devices: CecDiscoveredDevice[] = [];
  let current: CecDiscoveredDevice | null = null;

  const finalizeCurrent = () => {
    if (!current) {
      return;
    }
    const vendorLower = current.vendor.toLowerCase();
    const osdLower = current.osdString.toLowerCase();
    current.isAppleTv = vendorLower.includes('apple') || osdLower.includes('apple');
    devices.push(current);
    current = null;
  };

  for (const rawLine of lines) {
    const line = rawLine.trim();
    if (!line) {
      continue;
    }

    const headerMatch = line.match(/^device\s+#([0-9a-fA-F]+)\s*:\s*(.+)$/i);
    if (headerMatch) {
      finalizeCurrent();
      const rawId = headerMatch[1].trim();
      const num = /^\d+$/.test(rawId) ? parseInt(rawId, 10) : parseInt(rawId, 16);
      const logicalAddress = Number.isNaN(num) ? rawId.toLowerCase() : num.toString(16).toLowerCase();
      current = {
        logicalAddress,
        logicalAddressNum: Number.isNaN(num) ? -1 : num,
        deviceType: headerMatch[2].trim(),
        physicalAddress: '',
        activeSource: false,
        vendor: '',
        osdString: '',
        isAppleTv: false,
      };
      continue;
    }

    if (!current) {
      continue;
    }

    const addressMatch = line.match(/^address\s*:\s*([0-9a-fA-F.]+)/i);
    if (addressMatch) {
      current.physicalAddress = addressMatch[1].trim();
      continue;
    }

    const activeMatch = line.match(/^active source\s*:\s*(.+)$/i);
    if (activeMatch) {
      const val = activeMatch[1].trim().toLowerCase();
      current.activeSource = val === 'yes' || val === 'true' || val === '1';
      continue;
    }

    const vendorMatch = line.match(/^vendor\s*:\s*(.+)$/i);
    if (vendorMatch) {
      current.vendor = vendorMatch[1].trim();
      continue;
    }

    const osdMatch = line.match(/^osd string\s*:\s*(.+)$/i);
    if (osdMatch) {
      current.osdString = osdMatch[1].trim();
    }
  }

  finalizeCurrent();
  return devices;
}

/**
 * Parse a `cec-client -d 8` incoming TRAFFIC line (e.g. `TRAFFIC: [  123] >> 45:44:41`).
 */
export function parseTrafficFrame(line: string): CecTrafficFrame | null {
  const arrowIdx = line.indexOf('>>');
  if (arrowIdx === -1) {
    return null;
  }

  const payload = line.slice(arrowIdx + 2).trim();
  const tokens = payload.split(/\s+/)[0]?.split(':').map((b) => b.trim().toLowerCase()) ?? [];
  if (tokens.length < 2) {
    return null;
  }

  const header = tokens[0];
  if (!/^[0-9a-f]{2}$/.test(header)) {
    return null;
  }

  for (let i = 1; i < tokens.length; i++) {
    if (!/^[0-9a-f]{2}$/.test(tokens[i])) {
      return null;
    }
  }

  return {
    src: header[0],
    dst: header[1],
    opcode: tokens[1],
    arg: tokens[2],
    bytes: tokens,
  };
}

export class Pulse8CecClient extends EventEmitter {
  private readonly cecClientPath: string;
  private readonly portPath?: string;
  private readonly osdName: string;
  private readonly hdmiPort?: number;
  private readonly holdMode: CecHoldMode;
  private readonly holdDelayMs: number;
  private readonly holdRepeatMs: number;
  private readonly holdSafetyMs: number;
  private readonly powerDebounceMs: number;
  private readonly ignoreStandbyAfterWakeMs: number;
  private readonly powerKeyMode: CecPowerKeyMode;
  private readonly rescanIntervalSec: number;
  private readonly rawSender?: (cmd: string) => void;

  private proc: ChildProcessWithoutNullStreams | null = null;
  private rl: readline.Interface | null = null;
  private respawnTimer: NodeJS.Timeout | null = null;
  private rescanTimer: NodeJS.Timeout | null = null;
  private scanSettleTimer: NodeJS.Timeout | null = null;

  private isShuttingDown = false;
  private adapterReady = false;
  private inScan = false;
  private scanBuffer: string[] = [];
  private lastScanRequestedAt = 0;
  private missingBinaryLogged = false;
  private consecutiveStartFailures = 0;
  private recentDiagnostics: string[] = [];

  // Discovered Apple TVs keyed by lowercase hex logical address nibble ('4', '8', 'b', ...)
  private readonly discoveredAppleTvs = new Map<string, CecDiscoveredDevice>();
  // Internal bus power tracking starting at null (unknown) so Standby works even if Apple TV was already awake at boot
  private readonly powerStates = new Map<string, boolean | null>();
  private readonly lastPowerTransitionAt = new Map<string, number>();
  private readonly lastWakeAt = new Map<string, number>();
  private readonly pendingPowerTimers = new Map<string, PendingPowerTransition>();
  // Active hold state per initiator logical address
  private readonly holds = new Map<string, HoldState>();

  constructor(
    options: CecClientOptions,
    private readonly log: CecLogger,
  ) {
    super();
    this.cecClientPath = options.cecClientPath?.trim() || 'cec-client';
    this.portPath = options.portPath?.trim() || undefined;
    this.osdName = (options.osdName?.trim() || 'Homebridge').slice(0, 14);
    this.hdmiPort =
      typeof options.hdmiPort === 'number' && options.hdmiPort >= 1 && options.hdmiPort <= 15
        ? Math.floor(options.hdmiPort)
        : undefined;
    this.holdMode = options.holdMode === 'repeat' ? 'repeat' : 'longPress';
    this.holdDelayMs = options.holdDelayMs ?? 400;
    this.holdRepeatMs = options.holdRepeatMs ?? 150;
    this.holdSafetyMs = options.holdSafetyMs ?? 5000;
    this.powerDebounceMs = Math.max(0, options.powerDebounceMs ?? 1500);
    this.ignoreStandbyAfterWakeMs = Math.max(0, options.ignoreStandbyAfterWakeMs ?? 0);
    this.powerKeyMode = options.powerKeyMode === 'handle' ? 'handle' : 'ignore';
    this.rescanIntervalSec = options.rescanIntervalSec ?? 0;
    this.rawSender = options.rawSender;
  }

  public start(): void {
    if (this.isShuttingDown) {
      return;
    }

    if (this.respawnTimer) {
      clearTimeout(this.respawnTimer);
      this.respawnTimer = null;
    }

    const resolvedBinary = resolveCecClientPath({ configuredPath: this.cecClientPath });
    if (!resolvedBinary) {
      const retryDelayMs = 60000;
      const isDefaultName =
        this.cecClientPath === 'cec-client' &&
        !this.cecClientPath.includes('/') &&
        !this.cecClientPath.includes('\\');
      const msg = isDefaultName
        ? '[CEC] Could not find "cec-client" in PATH or standard locations (/opt/homebrew/bin, /usr/local/bin, /usr/bin). Install libcec (macOS: "brew install libcec", Debian/Ubuntu: "sudo apt-get install -y cec-utils") or set "cecClientPath" in plugin config. Checking again in 60s...'
        : `[CEC] Configured cecClientPath "${this.cecClientPath}" was not found or is not executable. Update "cecClientPath" in plugin config. Checking again in 60s...`;

      if (!this.missingBinaryLogged) {
        this.missingBinaryLogged = true;
        this.log.error(msg);
      } else {
        this.log.debug(msg);
      }

      this.respawnTimer = setTimeout(() => this.start(), retryDelayMs);
      return;
    }

    this.missingBinaryLogged = false;
    this.recentDiagnostics = [];

    const args = ['-t', 'a', '-d', '8'];
    if (this.osdName) {
      args.push('-o', this.osdName);
    }
    if (this.hdmiPort !== undefined) {
      args.push('-p', String(this.hdmiPort));
    }
    if (this.portPath) {
      args.push(this.portPath);
    }

    this.adapterReady = false;
    this.log.info(
      `[CEC] Starting ${resolvedBinary} ${args.join(' ')}`,
    );

    let spawnError: NodeJS.ErrnoException | null = null;
    const proc = spawn(resolvedBinary, args, { env: buildAugmentedEnv() });
    this.proc = proc;

    this.rl = readline.createInterface({ input: proc.stdout });
    this.rl.on('line', (line: string) => this.handleLine(line));

    proc.stderr.on('data', (data: Buffer) => {
      const msg = data.toString('utf8').trim();
      if (msg) {
        this.pushDiagnostic(msg);
        this.log.debug(`[CEC stderr] ${msg}`);
      }
    });

    proc.on('error', (err: NodeJS.ErrnoException) => {
      spawnError = err;
      this.log.error(`[CEC] Failed to spawn ${resolvedBinary}: ${err.message}`);
    });

    proc.on('close', (code: number | null) => {
      this.stopAllHolds();
      this.clearAllPendingPowerTimers();
      this.clearScanTimers();
      const wasReady = this.adapterReady;
      this.adapterReady = false;
      if (this.rl) {
        this.rl.close();
        this.rl = null;
      }
      this.proc = null;

      if (this.isShuttingDown) {
        return;
      }

      if (spawnError) {
        const retryMs =
          spawnError.code === 'ENOENT' || spawnError.code === 'EACCES' ? 60000 : 10000;
        this.log.warn(`[CEC] Unable to launch cec-client (${spawnError.code || spawnError.message}). Retrying in ${Math.round(retryMs / 1000)}s...`);
        this.respawnTimer = setTimeout(() => this.start(), retryMs);
        return;
      }

      if (!wasReady && code !== 0 && this.recentDiagnostics.length > 0) {
        this.log.warn(`[CEC] Diagnostic output: ${this.recentDiagnostics.join(' | ')}`);
      }

      this.consecutiveStartFailures = wasReady ? 0 : this.consecutiveStartFailures + 1;
      const respawnDelayMs =
        this.consecutiveStartFailures >= 5
          ? 30000
          : this.consecutiveStartFailures >= 3
            ? 15000
            : 3000;

      this.log.warn(
        `[CEC] cec-client exited with code ${code ?? 'unknown'}. Respawning in ${Math.round(respawnDelayMs / 1000)}s...`,
      );
      this.respawnTimer = setTimeout(() => this.start(), respawnDelayMs);
    });

    if (this.rescanIntervalSec > 0 && !this.rescanTimer) {
      this.rescanTimer = setInterval(() => {
        if (this.adapterReady) {
          this.runScan();
        }
      }, this.rescanIntervalSec * 1000);
    }
  }

  public stop(): void {
    this.isShuttingDown = true;
    this.stopAllHolds();
    this.clearAllPendingPowerTimers();
    this.clearScanTimers();

    if (this.respawnTimer) {
      clearTimeout(this.respawnTimer);
      this.respawnTimer = null;
    }
    if (this.rescanTimer) {
      clearInterval(this.rescanTimer);
      this.rescanTimer = null;
    }
    if (this.rl) {
      this.rl.close();
      this.rl = null;
    }
    if (this.proc) {
      try {
        this.sendRaw('q');
      } catch {
        // Ignore write failures during shutdown
      }
      this.proc.kill('SIGTERM');
      this.proc = null;
    }
  }

  public getDiscoveredAppleTvs(): CecDiscoveredDevice[] {
    return Array.from(this.discoveredAppleTvs.values());
  }

  public getBusPowerState(logicalAddress: string): boolean | null {
    return this.powerStates.get(logicalAddress.toLowerCase()) ?? null;
  }

  public runScan(): void {
    const now = Date.now();
    this.lastScanRequestedAt = now;
    this.inScan = false;
    this.scanBuffer = [];
    this.log.debug('[CEC] Running bus scan...');
    this.sendRaw('scan');
  }

  public sendRaw(cmd: string): void {
    if (this.rawSender) {
      this.rawSender(cmd);
      return;
    }
    if (this.proc && this.proc.stdin && this.proc.stdin.writable) {
      this.proc.stdin.write(`${cmd}\n`);
    }
  }

  public enableSystemAudioMode(): void {
    this.sendRaw('tx 5F:72:01');
  }

  public handleLine(line: string): void {
    const trimmed = line.trim();
    if (!trimmed) {
      return;
    }

    if (
      !this.adapterReady &&
      /\b(error|failed|unable to|permission denied|no adapters found)\b/i.test(trimmed)
    ) {
      this.pushDiagnostic(trimmed);
    }

    // 1. Capture `scan` output lines
    if (/^device\s+#[0-9a-fA-F]+\s*:/i.test(trimmed)) {
      this.inScan = true;
      this.scanBuffer.push(trimmed);
      this.scheduleScanSettle();
      return;
    }

    if (this.inScan) {
      if (
        /^(address|active source|vendor|osd string|cec version|power status|language)\s*:/i.test(trimmed)
      ) {
        this.scanBuffer.push(trimmed);
        this.scheduleScanSettle();
        return;
      }

      if (/^currently active source\s*:/i.test(trimmed)) {
        this.finalizeScan();
        return;
      }
    }

    // 2. Adapter ready detection -> claim System Audio Mode + scan HDMI bus
    if (
      !this.adapterReady &&
      (trimmed.includes('waiting for input') || trimmed.includes('TRAFFIC:') || trimmed.includes('>>'))
    ) {
      this.adapterReady = true;
      this.consecutiveStartFailures = 0;
      this.log.info('[CEC] Pulse-Eight adapter ready. Enabling System Audio Mode and scanning bus...');
      this.enableSystemAudioMode();
      if (trimmed.includes('waiting for input')) {
        this.runScan();
        return;
      }
      this.runScan();
    }

    // 3. Parse incoming CEC traffic frames
    const frame = parseTrafficFrame(trimmed);
    if (!frame) {
      return;
    }

    this.handleTrafficFrame(frame);
  }

  private pushDiagnostic(msg: string): void {
    this.recentDiagnostics.push(msg);
    if (this.recentDiagnostics.length > 6) {
      this.recentDiagnostics.shift();
    }
  }

  private scheduleScanSettle(): void {
    if (this.scanSettleTimer) {
      clearTimeout(this.scanSettleTimer);
    }
    this.scanSettleTimer = setTimeout(() => {
      this.finalizeScan();
    }, 400);
  }

  private finalizeScan(): void {
    if (this.scanSettleTimer) {
      clearTimeout(this.scanSettleTimer);
      this.scanSettleTimer = null;
    }
    if (!this.inScan) {
      return;
    }
    this.inScan = false;
    const lines = this.scanBuffer;
    this.scanBuffer = [];

    const allDevices = parseScanOutput(lines);
    const appleTvs = allDevices.filter((d) => d.isAppleTv);

    this.discoveredAppleTvs.clear();
    for (const atv of appleTvs) {
      this.discoveredAppleTvs.set(atv.logicalAddress, atv);
    }

    if (appleTvs.length === 0) {
      this.log.warn(
        `[CEC] Scan found ${allDevices.length} CEC device(s), but no Apple TV yet. Make sure Apple TV has 'Control TVs and Receivers' ON.`,
      );
    } else {
      const summary = appleTvs
        .map((d) => `${d.osdString || 'Apple TV'} (logical=${d.logicalAddress}, physical=${d.physicalAddress || 'unknown'})`)
        .join(', ');
      this.log.info(`[CEC] Scan discovered ${appleTvs.length} Apple TV(s): ${summary}`);
    }

    this.emit('scanResult', { devices: allDevices, appleTvs });
  }

  private clearScanTimers(): void {
    if (this.scanSettleTimer) {
      clearTimeout(this.scanSettleTimer);
      this.scanSettleTimer = null;
    }
    this.inScan = false;
    this.scanBuffer = [];
  }

  private isAllowedInitiator(src: string): boolean {
    if (this.discoveredAppleTvs.has(src)) {
      return true;
    }
    // If scan hasn't found any Apple TV yet (e.g. Apple TV was asleep at boot), allow playback initiators
    // and trigger a debounced scan so the Apple TV gets discovered and registered dynamically.
    if (PLAYBACK_LOGICAL_ADDRESSES.has(src)) {
      const now = Date.now();
      if (now - this.lastScanRequestedAt > 10000) {
        this.runScan();
      }
      return this.discoveredAppleTvs.size === 0;
    }
    return false;
  }

  private handleTrafficFrame(frame: CecTrafficFrame): void {
    const { src, dst, opcode, arg } = frame;

    // Frames directed to our emulated Audio System (Logical Address 5)
    if (dst === '5') {
      // Keep System Audio Mode alive across tvOS requests & status polls
      if (opcode === '70' || opcode === '7d') {
        this.enableSystemAudioMode();
        return;
      }

      // Give Audio Status -> Report Audio Status (50%, unmuted) to actual initiator
      if (opcode === '71') {
        this.sendRaw(`tx 5${src}:7a:32`);
        return;
      }

      // Give Device Power Status -> Report Power Status = On (0x00) to actual initiator
      if (opcode === '8f') {
        this.sendRaw(`tx 5${src}:90:00`);
        return;
      }

      // Remote Key Presses (User Control Pressed 0x44 / Released 0x45)
      if (!this.isAllowedInitiator(src)) {
        return;
      }

      if (opcode === '44') {
        if (arg === '41') {
          this.handleVolumeKeyPress(src, 'volumeUp');
        } else if (arg === '42') {
          this.handleVolumeKeyPress(src, 'volumeDown');
        } else if (arg === '43') {
          this.stopHold(src);
          this.emitKeyEvent(src, 'mute', 'single');
          this.emitVolumeCommand(src, 'mute', false);
        } else if (arg === '40' || arg === '6b' || arg === '6c' || arg === '6d') {
          this.handleRemotePowerKey(src, arg);
        }
        return;
      }

      if (opcode === '45') {
        this.handleVolumeKeyRelease(src);
      }
      return;
    }

    // Broadcast / TV-directed frames
    // Explicitly skip Report Physical Address (0x84) to avoid spamming tx 5F:72:01 on the bus
    if (dst === 'f' && opcode === '84') {
      return;
    }

    if (!this.isAllowedInitiator(src)) {
      return;
    }

    // Active Source (0x82) or Image View On (0x04) -> re-assert System Audio Mode so Siri Remote stays in HDMI-CEC volume mode
    if ((dst === 'f' && opcode === '82') || ((dst === '0' || dst === 'f') && opcode === '04')) {
      this.enableSystemAudioMode();
      this.recordPowerState(src, true, 'bus');
      return;
    }

    // Standby (0x36)
    if (dst === 'f' && opcode === '36') {
      this.stopHold(src);
      this.recordPowerState(src, false, 'bus');
    }
  }

  private handleRemotePowerKey(src: string, arg: string): void {
    if (this.powerKeyMode === 'ignore') {
      this.log.debug(`[CEC] Ignoring remote power key (44:${arg}) from logical address ${src}`);
      return;
    }

    if (arg === '6d') {
      // Dedicated Power On Function
      this.emitKeyEvent(src, 'powerOn', 'single');
      if (this.getBusPowerState(src) === true) {
        this.emitAction(src, 'powerOn', false, 'key');
      } else {
        this.recordPowerState(src, true, 'key');
      }
      return;
    }

    if (arg === '6c') {
      // Dedicated Power Off Function
      this.stopHold(src);
      this.emitKeyEvent(src, 'powerOff', 'single');
      if (this.getBusPowerState(src) === false) {
        this.emitAction(src, 'powerOff', false, 'key');
      } else {
        this.recordPowerState(src, false, 'key');
      }
      return;
    }

    // Power Toggle (44:40 / 44:6b)
    const current = this.getBusPowerState(src);
    if (current === null) {
      // Unknown current state: emit semantic powerToggle + powerOn key, and set state to true
      this.emitKeyEvent(src, 'powerOn', 'single');
      this.recordPowerState(src, true, 'key', 'powerToggle');
    } else {
      const next = !current;
      if (!next) {
        this.stopHold(src);
      }
      this.emitKeyEvent(src, next ? 'powerOn' : 'powerOff', 'single');
      this.recordPowerState(src, next, 'key');
    }
  }

  private recordPowerState(
    src: string,
    turnOn: boolean,
    source: 'bus' | 'key',
    overrideAction?: CecSemanticAction,
  ): void {
    const now = Date.now();
    const prev = this.powerStates.get(src) ?? null;
    const pending = this.pendingPowerTimers.get(src);

    if (prev === turnOn) {
      // Steady state reached again; cancel any pending opposite flicker transition
      if (pending && pending.targetState !== turnOn) {
        this.clearPendingPowerTimer(src);
        this.log.debug(
          `[CEC] Cancelled pending ${pending.targetState ? 'ON' : 'OFF'} flicker transition for ${src}`,
        );
      }
      return;
    }

    // Optional guard: ignore Standby (0x36) immediately after wake
    if (!turnOn && source === 'bus' && this.ignoreStandbyAfterWakeMs > 0) {
      const wakeAt = this.lastWakeAt.get(src) ?? 0;
      if (wakeAt > 0 && now - wakeAt < this.ignoreStandbyAfterWakeMs) {
        this.log.debug(
          `[CEC] Ignoring Standby (0x36) for ${src} (${now - wakeAt}ms after wake < ${this.ignoreStandbyAfterWakeMs}ms)`,
        );
        return;
      }
    }

    // Guard against rapid true <-> false flicker using powerDebounceMs settle window
    const lastTransitionAt = this.lastPowerTransitionAt.get(src) ?? 0;
    if (prev !== null && lastTransitionAt > 0 && this.powerDebounceMs > 0) {
      const elapsed = now - lastTransitionAt;
      if (elapsed < this.powerDebounceMs) {
        if (pending && pending.targetState === turnOn) {
          return;
        }
        this.clearPendingPowerTimer(src);
        const delayMs = this.powerDebounceMs - elapsed;
        const timer = setTimeout(() => {
          this.pendingPowerTimers.delete(src);
          this.applyPowerTransition(src, turnOn, source, overrideAction);
        }, delayMs);
        timer.unref();
        this.pendingPowerTimers.set(src, { targetState: turnOn, source, timer });
        this.log.debug(
          `[CEC] Debouncing rapid power flicker for ${src} -> ${turnOn ? 'ON' : 'OFF'} (${delayMs}ms)`,
        );
        return;
      }
    }

    this.clearPendingPowerTimer(src);
    this.applyPowerTransition(src, turnOn, source, overrideAction);
  }

  private applyPowerTransition(
    src: string,
    turnOn: boolean,
    source: 'bus' | 'key',
    overrideAction?: CecSemanticAction,
  ): void {
    const now = Date.now();
    const prev = this.powerStates.get(src) ?? null;
    if (prev === turnOn) {
      return;
    }

    this.powerStates.set(src, turnOn);
    if (turnOn) {
      this.lastWakeAt.set(src, now);
    }
    // Only treat boolean <-> boolean or initial wake (null -> true) as active transitions for flicker debounce,
    // so initial null -> false (standby observed at boot) does not delay an immediate wake.
    if (prev !== null || turnOn) {
      this.lastPowerTransitionAt.set(src, now);
    }

    this.log.debug(`[CEC] Power state for logical address ${src} -> ${turnOn ? 'ON' : 'OFF'} (via ${source})`);

    const powerEvent: CecPowerChangeEvent = {
      logicalAddress: src,
      powered: turnOn,
      previous: prev,
      source,
      timestamp: now,
    };
    this.emit('powerChange', powerEvent);

    const action: CecSemanticAction = overrideAction ?? (turnOn ? 'powerOn' : 'powerOff');
    this.emitAction(src, action, false, source, now);
  }

  private clearPendingPowerTimer(src: string): void {
    const pending = this.pendingPowerTimers.get(src);
    if (pending) {
      clearTimeout(pending.timer);
      this.pendingPowerTimers.delete(src);
    }
  }

  private clearAllPendingPowerTimers(): void {
    for (const pending of this.pendingPowerTimers.values()) {
      clearTimeout(pending.timer);
    }
    this.pendingPowerTimers.clear();
  }

  private handleVolumeKeyPress(src: string, key: 'volumeUp' | 'volumeDown'): void {
    const existing = this.holds.get(src);
    if (existing && existing.key === key) {
      // Some remotes/adapters re-send 44:41 while held; refresh safety timeout without restarting tap detection
      if (existing.safetyTimer) {
        clearTimeout(existing.safetyTimer);
      }
      existing.safetyTimer = setTimeout(() => {
        this.stopHold(src);
      }, this.holdSafetyMs);
      return;
    }

    this.stopHold(src);

    const hold: HoldState = {
      key,
      longFired: false,
      delayTimer: null,
      repeatTimer: null,
      directDelayTimer: null,
      directRepeatTimer: null,
      safetyTimer: null,
    };

    // Always emit an immediate direct volume command on press
    this.emitVolumeCommand(src, key, false);

    if (this.holdMode === 'repeat') {
      this.emitKeyEvent(src, key, 'single');
      hold.delayTimer = setTimeout(() => {
        this.emitKeyEvent(src, key, 'single');
        this.emitVolumeCommand(src, key, true);
        hold.repeatTimer = setInterval(() => {
          this.emitKeyEvent(src, key, 'single');
          this.emitVolumeCommand(src, key, true);
        }, this.holdRepeatMs);
      }, this.holdDelayMs);
    } else {
      hold.delayTimer = setTimeout(() => {
        hold.longFired = true;
        this.emitKeyEvent(src, key, 'long');
      }, this.holdDelayMs);

      // Even when HomeKit buttons use longPress mode, direct target volume control smoothly steps while held
      hold.directDelayTimer = setTimeout(() => {
        this.emitVolumeCommand(src, key, true);
        hold.directRepeatTimer = setInterval(() => {
          this.emitVolumeCommand(src, key, true);
        }, this.holdRepeatMs);
      }, this.holdDelayMs);
    }

    hold.safetyTimer = setTimeout(() => {
      this.stopHold(src);
    }, this.holdSafetyMs);

    this.holds.set(src, hold);
  }

  private handleVolumeKeyRelease(src: string): void {
    const existing = this.holds.get(src);
    if (!existing) {
      return;
    }

    const shouldEmitSingleTap = this.holdMode === 'longPress' && !existing.longFired;
    const key = existing.key;
    this.stopHold(src);

    if (shouldEmitSingleTap) {
      this.emitKeyEvent(src, key, 'single');
    }
  }

  private stopHold(src: string): void {
    const existing = this.holds.get(src);
    if (!existing) {
      return;
    }
    if (existing.delayTimer) {
      clearTimeout(existing.delayTimer);
    }
    if (existing.repeatTimer) {
      clearInterval(existing.repeatTimer);
    }
    if (existing.directDelayTimer) {
      clearTimeout(existing.directDelayTimer);
    }
    if (existing.directRepeatTimer) {
      clearInterval(existing.directRepeatTimer);
    }
    if (existing.safetyTimer) {
      clearTimeout(existing.safetyTimer);
    }
    this.holds.delete(src);
  }

  private stopAllHolds(): void {
    for (const src of Array.from(this.holds.keys())) {
      this.stopHold(src);
    }
  }

  private emitKeyEvent(logicalAddress: string, key: CecKeyType, pressType: CecPressType): void {
    const event: CecKeyEvent = {
      logicalAddress,
      key,
      pressType,
      timestamp: Date.now(),
    };
    this.log.info(`[CEC] Apple TV (${logicalAddress}) ${key} -> ${pressType.toUpperCase()}`);
    this.emit('keyPress', event);
  }

  private emitVolumeCommand(
    logicalAddress: string,
    key: 'volumeUp' | 'volumeDown' | 'mute',
    isRepeat: boolean,
  ): void {
    const timestamp = Date.now();
    const event: CecVolumeCommandEvent = {
      logicalAddress,
      key,
      isRepeat,
      timestamp,
    };
    this.emit('volumeCommand', event);

    const semanticAction: CecSemanticAction = key === 'mute' ? 'muteToggle' : key;
    this.emitAction(logicalAddress, semanticAction, isRepeat, 'key', timestamp);
  }

  private emitAction(
    logicalAddress: string,
    action: CecSemanticAction,
    isRepeat: boolean,
    source: 'key' | 'bus',
    timestamp = Date.now(),
  ): void {
    const event: CecActionEvent = {
      logicalAddress,
      action,
      isRepeat,
      source,
      timestamp,
    };
    this.emit('action', event);
  }
}
